const own = (value, key) => Object.prototype.hasOwnProperty.call(value,key);
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const interfaceID = Object.keys(meta.parameterInterfaces)[0];

function duration(value) {
  if (!(typeof value === 'number' && Number.isInteger(value)) && !(typeof value === 'string' && /^\d+$/.test(value))) throw new Error('seconds 必须是整数秒数');
  const n = Number(value);
  if (!Number.isSafeInteger(n) || n < 1 || n > 3600) throw new Error('seconds 必须在 1 至 3600 秒之间');
  return n;
}

function reference(value) {
  if (object(value) && Object.keys(value).every(key=>key==='url')) value=value.url;
  if (typeof value !== 'string' || !/^https:\/\/[^\s/@?#]+(?:[/?#][^\s]*)?$/.test(value)) throw new Error('参考素材必须是可公开读取的 HTTPS URL');
  // Preserve signed URLs byte for byte. The host owns download/SSRF controls.
  return value;
}

function inputs(body) {
  if (!object(body)) throw new Error('请求体必须是 JSON 对象');
  const input = {};
  const aliases = {prompt:['prompt'],seconds:['seconds','duration','duration_seconds'],aspect_ratio:['aspect_ratio','size'],resolution:['resolution'],images:['images','reference_image_urls','image','input_reference'],videos:['videos','reference_videos'],audios:['audios','reference_audios']};
  for (const [field,names] of Object.entries(aliases)) {
    for (const name of names) {
      if (!own(body,name)) continue;
      let value=body[name];
      if (field==='seconds') {
        if (name==='duration' && (typeof value!=='number' || !Number.isInteger(value))) throw new Error('duration 必须是整数');
        value=duration(value);
      } else if (['images','videos','audios'].includes(field)) {
        if (['image','input_reference'].includes(name)) {
          if (typeof value!=='string') throw new Error(name+' 必须是单图 URL');
          value=[value];
        } else if (!Array.isArray(value)) throw new Error(name+' 必须是 URL 数组，不能是 JSON 字符串');
        value=value.map(reference);
      } else if (typeof value!=='string') throw new Error(name+' 必须是字符串');
      if (own(input,field) && JSON.stringify(input[field])!==JSON.stringify(value)) throw new Error(field+' 的别名值冲突，请只提供一套参数');
      input[field]=value;
    }
  }
  return input;
}

function normalized(ctx) {
  const body=ctx.requestBody || {};
  if (body.protocolTemplate!==interfaceID) throw new Error('请先选择并确认 AoTian /v1/videos 接口参数配置');
  if (body.operation!=='video_generate') throw new Error('接口仅支持创建视频');
  const input=inputs(body.input);
  if (typeof input.prompt!=='string' || !input.prompt.trim()) throw new Error('prompt 必填且不能为空');
  const model=ctx.upstreamModel || ctx.model;
  if (typeof model!=='string' || !model.trim()) throw new Error('model 必填');
  const unrestricted=new Set(body.unrestrictedValueFields || []);
  const ratios=meta.parameterInterfaces[interfaceID].parameters.aspect_ratio.definition.enum;
  if (input.aspect_ratio!==undefined && !unrestricted.has('aspect_ratio') && !ratios.includes(input.aspect_ratio)) throw new Error('size 不在文档画面比例范围内');
  const uploads=body.uploads || [];
  if (!Array.isArray(uploads) || uploads.length>1) throw new Error('multipart 仅支持一个 input_reference 文件');
  if (uploads.length) {
    const file=uploads[0];
    const actual=(ctx.files || []).find(item=>item.ref===file.ref);
    if (!actual || file.field!=='input_reference' || actual.field!==file.field) throw new Error('上传文件必须使用 input_reference');
    if (!['image/png','image/jpeg','image/webp'].includes(actual.mimeType) || !Number.isSafeInteger(actual.size) || actual.size<=0) throw new Error('参考图文件类型或大小无效');
    if (['images','videos','audios'].some(field=>input[field]?.length)) throw new Error('文件上传不能与参考素材 URL 数组混用');
  }
  return {input,uploads,model};
}

function apiRequest(ctx,path) {
  const base=String(ctx.baseUrl || meta.baseUrl).replace(/\/+$/,'').replace(/\/v1$/,'');
  if (!/^https:\/\/[^\s/@?#]+(?:\/[^\s?#]*)?$/.test(base)) throw new Error('渠道地址必须是 HTTPS URL');
  const authorization=ctx.authHeader || (ctx.apiKey ? 'Bearer '+ctx.apiKey : '');
  if (!authorization || /[\r\n]/.test(authorization)) throw new Error('渠道 API 密钥未配置');
  return {url:base+path,method:'GET',headers:{Authorization:authorization,Accept:'application/json'}};
}

export function buildSubmitRequest(ctx) {
  const r=normalized(ctx),body={model:r.model,prompt:r.input.prompt};
  if (r.input.seconds!==undefined) body.seconds=String(r.input.seconds);
  if (r.input.aspect_ratio!==undefined) body.size=r.input.aspect_ratio;
  if (r.input.resolution!==undefined) body.resolution=r.input.resolution;
  for (const [field,vendor] of [['images','images'],['videos','reference_videos'],['audios','reference_audios']]) if (r.input[field]?.length) body[vendor]=r.input[field];
  const descriptor=apiRequest(ctx,'/v1/videos');
  descriptor.method='POST';
  if (r.uploads.length) {
    descriptor.bodyType='multipart';
    descriptor.parts=Object.entries(body).map(([name,value])=>({name,value:String(value)}));
    const file=r.uploads[0];
    descriptor.parts.push({name:'input_reference',fileRef:file.ref,filename:file.filename});
  } else {
    descriptor.headers['Content-Type']='application/json';
    descriptor.body=body;
  }
  return descriptor;
}

function resultURL(body) {
  if (!object(body) || typeof body.url!=='string' || !/^https:\/\/[^\s/@?#]+(?:[/?#][^\s]*)?$/.test(body.url)) return '';
  return body.url;
}

function failureReason(body) {
  const reason=object(body.error) ? body.error.message : typeof body.error==='string' ? body.error : body.fail_reason;
  // Provider text may reflect request data; strip credentials and signed URLs.
  return typeof reason==='string' && reason.trim() ? reason.replace(/https?:\/\/\S+/gi,'[URL]').replace(/Bearer\s+\S+/gi,'Bearer [redacted]').replace(/\bsk-[A-Za-z0-9_-]+/g,'[redacted]').slice(0,2048) : '上游视频任务失败';
}

export function parseTaskResult(ctx,body) {
  if (!object(body)) return {status:'UNKNOWN',reason:'上游任务响应不是 JSON 对象'};
  const status=typeof body.status==='string' ? body.status.toLowerCase() : '';
  if (['failed','failure','cancelled','canceled'].includes(status) || body.success===false || body.error) return {status:'FAILURE',progress:'100%',reason:failureReason(body)};
  if (['completed','success','succeeded'].includes(status)) {
    const url=resultURL(body);
    return url ? {status:'SUCCESS',progress:'100%',url} : {status:'UNKNOWN',reason:'完成响应缺少有效视频 URL'};
  }
  if (status==='queued') return {status:'QUEUED',progress:'0%'};
  if (['in_progress','processing'].includes(status)) {
    const progress=Number(body.progress);
    return {status:'IN_PROGRESS',progress:(Number.isFinite(progress) ? Math.max(0,Math.min(99,Math.round(progress))) : 0)+'%'};
  }
  return {status:'UNKNOWN',reason:'未识别上游任务状态'};
}

function taskID(value) {
  if (typeof value!=='string' || !value.trim() || value.length>512 || /[\s\x00-\x1f\x7f]/.test(value)) throw new Error('创建响应缺少有效任务 ID');
  return value;
}

export function parseSubmitResponse(ctx,response) {
  const body=response.body;
  if (!object(body)) throw new Error('上游创建响应不是 JSON 对象，请核对任务记录，勿重复创建');
  const result=parseTaskResult(ctx,body);
  const id=body.id;
  // Accepted terminal failures must follow settlement/refund, never throw a
  // retryable parser error just because the failure has no upstream task ID.
  if (result.status==='FAILURE') return {taskId:typeof id==='string'&&id ? taskID(id) : ctx.publicTaskId || utils.uuid(),taskData:body,immediate:result};
  const parsed={taskId:taskID(id),taskData:body,state:{protocolTemplate:interfaceID}};
  if (result.status==='SUCCESS') parsed.immediate=result;
  return parsed;
}

export function buildQueryRequest(ctx) {
  return apiRequest(ctx,'/v1/videos/'+encodeURIComponent(taskID(ctx.taskId)));
}

export function extractUsage(ctx) {
  normalized(ctx);
  if (ctx.usagePurpose==='billing_ratios') throw new Error('请先配置该模型的插件计费表达式');
  return {request_count:1};
}

export function extractUsageOnComplete() {
  // No documented general actual-output-duration field. Never infer usage from
  // echoed request seconds, filenames, model names or monetary deductions.
  return {};
}

export function listArtifacts(task) {
  return task.status==='SUCCESS' && resultURL(task.data) ? [{key:'video',type:'video',mimeType:'video/mp4'}] : [];
}

export function buildContentRequest(ctx) {
  const url=resultURL(ctx.data);
  if (ctx.artifactKey!=='video' || !url) throw new Error('视频结果不可用');
  return {url,method:ctx.clientRequest?.method==='HEAD'?'HEAD':'GET',credentialless:true};
}

export const protocols = {
  openai_video:{
    decodeRequest(ctx) {
      const body=ctx.body || {};
      let value, uploads=[];
      if (body.kind==='json') value=body.value;
      else if (body.kind==='multipart') {
        value={}; uploads=body.files || [];
        for (const [name,values] of Object.entries(body.fields || {})) {
          if (['__proto__','prototype','constructor'].includes(name)) throw new Error('无效字段名');
          if (values.length!==1) throw new Error(name+' 只能填写一次');
          value[name]=values[0];
        }
      } else throw new Error('仅支持 JSON 或 multipart 请求');
      if (!object(value)) throw new Error('请求体必须是 JSON 对象');
      const input=JSON.parse(JSON.stringify(value));
      // The host applies confirmed channel policies, aliases and business
      // defaults after decoding. Do not restore filtered fields in the driver.
      return {kind:'submit',model:ctx.model,action:'video_generate',requestBody:{operation:'video_generate',input,uploads}};
    },
    render(ctx,task) {
      const body=object(task.data) ? task.data : {};
      const output={};
      const url=resultURL(body);
      if (url) output.url=url;
      if (task.status==='FAILURE') output.error={code:'video_generation_failed',message:failureReason(body)};
      return output;
    },
  },
};
